#include <iostream>
#include <string>
#include <regex>
#include <algorithm>

int main() {
    int totalChars;
    std::cin >> totalChars;
    std::string inputString;
    std::cin >> inputString;

    std::regex pattern("\\([a-zA-Z_]*\\)");
    std::string replacedInput = std::regex_replace(inputString, pattern, "_");

    // Split by one or more underscores
    size_t start = 0;
    int maxPartSize = 0;
    for (size_t i = 0; i <= replacedInput.length(); ++i) {
        if (i == replacedInput.length() || replacedInput[i] == '_') {
            int length = i - start;
            if (length > maxPartSize) {
                maxPartSize = length;
            }
            start = i + 1;
        }
    }
    std::cout << maxPartSize << std::endl;

    int countInParentheses = 0;
    bool insideParentheses = false;
    int startIdx = -1, endIdx = -1;
    for (size_t i = 0; i < inputString.length(); ++i) {
        char c = inputString[i];
        if (c == '(') {
            insideParentheses = true;
            startIdx = i;
        } else if (c == ')' && insideParentheses) {
            insideParentheses = false;
            endIdx = i;
            std::string innerContent = inputString.substr(startIdx + 1, endIdx - startIdx - 1);
            if (!innerContent.empty()) {
                // Split innerContent by underscores
                size_t innerStart = 0;
                int segmentsCount = 0;
                for (size_t j = 0; j <= innerContent.length(); ++j) {
                    if (j == innerContent.length() || innerContent[j] == '_') {
                        segmentsCount++;
                        innerStart = j + 1;
                    }
                }
                // Adjust count if innerContent starts with underscore
                if (!innerContent.empty() && innerContent[0] == '_') {
                    segmentsCount -= 1;
                }
                countInParentheses += segmentsCount;
            }
        }
    }
    std::cout << countInParentheses << std::endl;
    return 0;
}
